package com.punjab.oms.ar.dao.finance;
import com.punjab.oms.ar.ArApplication;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-outbox-schema：仅独立测试库的通知存储约束。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.outbox-schema.real",matches="true") @EnabledIfSystemProperty(named="ar.outbox-schema.real.commit",matches="true")
class OutboxSchemaRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String file:List.of("V002__ar_audit.sql","V011__ar_outbox.sql")){var path=Path.of("../scratch/dbddl/"+file);if(Files.exists(path))for(String sql:Files.readString(path).split(";"))if(!sql.isBlank())jdbc.execute(sql);}}
 long event(){String key=UUID.randomUUID().toString();jdbc.update("INSERT INTO oms_ar_lifecycle_event(event_type,occurred_at,actor,correlation_id,created_by,updated_by) VALUES('TEST',NOW(6),'test',?,'test','test')",key);return jdbc.queryForObject("SELECT id FROM oms_ar_lifecycle_event WHERE correlation_id=?",Long.class,key);}
 void insert(long event,String destination){jdbc.update("INSERT INTO oms_ar_outbox(event_id,legal_entity_id,destination,payload,created_by,updated_by) VALUES(?,1,?,'{}','test','test')",event,destination);}
 @Test @DisplayName("事件目的地唯一且待发送默认状态完整")void unique(){long event=event();insert(event,"FINANCE_EVENTS");assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE event_id=?",String.class,event)).isEqualTo("PENDING");assertThatThrownBy(()->insert(event,"FINANCE_EVENTS")).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);insert(event,"OTHER");}
 @Test @DisplayName("处理中租约必填，非处理中不能遗留租约")void lease(){long event=event();insert(event,"FINANCE_EVENTS");assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET status='PROCESSING' WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));jdbc.update("UPDATE oms_ar_outbox SET status='PROCESSING',lease_token=?,lease_until=DATE_ADD(NOW(6),INTERVAL 60 SECOND) WHERE event_id=?",UUID.randomUUID().toString(),event);assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET status='RETRY' WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));jdbc.update("UPDATE oms_ar_outbox SET status='RETRY',lease_token=NULL,lease_until=NULL WHERE event_id=?",event);}
 @Test @DisplayName("成功状态必须记录发送时间且计数不能为负")void status(){long event=event();insert(event,"FINANCE_EVENTS");assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET status='SENT' WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));jdbc.update("UPDATE oms_ar_outbox SET status='SENT',sent_time=NOW(6) WHERE event_id=?",event);assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET attempt_count=-1 WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET status='INVALID' WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));}
 @Test @DisplayName("无事件不能入队，主体不可无效")void references(){assertThatThrownBy(()->insert(Long.MAX_VALUE,"FINANCE_EVENTS")).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);long event=event();insert(event,"FINANCE_EVENTS");assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox SET legal_entity_id=0 WHERE event_id=?",event)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));}
}
